Object.assign(window.TEM8_DICTIONARY, {"operate":{"oxford":{"phon":"ˈɒpəreɪt","pos":"verb","senses":[{"en":"to work in a particular way","cn":"运转；工作","g":"[intransitive]","lab":"figurative","sc":"machine","ex":{"en":"Most domestic freezers operate at below −18°C.","cn":"多数家用冰柜能制冷到零下 18 摄氏度以下。"}},{"en":"to use or control a machine or make it work","cn":"操作；控制；使运行","g":"[transitive]","sc":"machine","ex":{"en":"What skills are needed to operate this machinery?","cn":"操作这种机器需要什么技能？"}},{"en":"to manage a business, organization or service","cn":"管理一项业务、组织或服务","g":"[transitive]","sc":"business/organization/service","ex":{"en":"The airline currently operates flights to 25 countries.","cn":"这家航空公司目前运营飞往 25 个国家的航班。"}},{"en":"to work, especially in a particular way or from a particular place","cn":"（尤指以某方式或以某地为据点）经营，营业","g":"[intransitive]","sc":"business/organization/service","ex":{"en":"A new late-night service is now operating.","cn":"现在推出一项新的深夜服务。"}},{"en":"to be used or working; to use something or make it work","cn":"（被）使用；（使）运转","g":"[intransitive, transitive]","sc":"system/process","ex":{"en":"The regulation operates in favour of married couples.","cn":"这一规定的实施有利于已婚夫妇。"}},{"en":"to cut open somebody’s body in order to remove a part that has a disease or to repair a part that is damaged","cn":"动手术","g":"[intransitive]","sc":"medical","ex":{"en":"Surgeons operated last night.","cn":"外科医生昨夜做手术了。"}},{"en":"to be involved in military activities in a place","cn":"（在某地）采取军事行动","g":"[intransitive]","sc":"of soldiers","ex":{"en":"Troops are operating from bases in the north.","cn":"部队正从北部基地发动军事行动。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"经营；管理；运营；运作","en":"If you operate a business or organization, you work to keep it running properly. If a business or organization operates, it carries out its work.","ex":{"en":"Until his death in 1986 Greenwood owned and operated an enormous pear orchard.","cn":"到他1986年去世前，格林伍德一直拥有并管理着一片面积广阔的梨园。"}},{"pos":"VERB 动词","cn":"工作；起作用","en":"The way that something operates is the way that it works or has a particular effect.","ex":{"en":"Ceiling and wall lights can operate independently","cn":"吊灯和壁灯可单独开关。"}},{"pos":"V-ERG 及物/不及物动词","cn":"操作，控制，使用（机器、设备等）；（机器等）运转，运行","en":"When you operate a machine or device, or when it operates, you make it work.","ex":{"en":"A massive rock fall trapped the men as they operated a tunnelling machine","cn":"这些工人在操作隧道挖掘机时被大量的落石困住了。"}},{"pos":"VERB 动词","cn":"（对…）动手术","en":"When surgeons operate on a patient in a hospital, they cut open a patient's body in order to remove, replace, or repair a diseased or damaged part.","ex":{"en":"The surgeon who operated on the King released new details of his injuries","cn":"为国王动手术的外科医生通报了其伤势的最新详情。"}},{"pos":"VERB 动词","cn":"（在某一地区）作战，执行任务","en":"If military forces are operating in a particular region, they are in that place in order to carry out their orders.","ex":{"en":"Up to ten thousand Zimbabwean soldiers are operating in Mozambique","cn":"多达1万名津巴布韦士兵正在莫桑比克执行任务。"}}]},"media":{"uk":"media/uk/operate__gb_1.mp3","us":"media/us/operate__us_1.mp3"},"examples":[{"en":"Most domestic freezers operate at below −18 °C.","cn":"多数家用冰柜能制冷到零下 18 摄氏度以下。"},{"en":"The airline operates flights to 25 countries.","cn":"这家航空公司经营飞往 25 个国家的航班。"}]},"opposing":{"oxford":{"phon":"əˈpəʊzɪŋ","pos":"adjective","senses":[{"en":"playing, fighting, working, etc. against each other","cn":"对立的；相竞争的；对抗的","ex":{"en":"a player from the opposing side","cn":"对方的运动员"}},{"en":"very different from each other","cn":"相反的；极不相同的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（观点、倾向等）对立的，截然相反的","en":"Opposing ideas or tendencies are totally different from each other.","ex":{"en":"I have a friend who has the opposing view and felt that the war was immoral","cn":"我有一位朋友的看法截然不同，他认为这场战争是不道德的。"}},{"pos":"ADJ 形容词","cn":"（群体等）对立的，对抗的","en":"Opposing groups of people disagree about something or are in competition with one another.","ex":{"en":"The Georgian leader said in a radio address that he still favoured dialogue between the opposing sides","cn":"这位格鲁吉亚领导人在广播讲话中称他依然赞成对立双方进行对话。"}}]},"media":{"uk":"media/uk/opposing__gb_1.mp3","us":"media/us/opposing__us_1.mp3"},"examples":[{"en":"It is time for opposing factions to unite and work towards a common goal.","cn":"现在是对立各派联合起来、为共同目标而奋斗的时候了。"},{"en":"a player from the opposing side","cn":"对方的运动员"}],"base":"oppose"},"openly":{"media":{"uk":"media/uk/openly__gb_1.mp3","us":"media/us/openly__us_1.mp3"},"oxford":{"phon":"ˈəʊpənli","pos":"adverb","senses":[{"en":"without hiding any feelings, opinions or information","cn":"公开地；毫不隐瞒地","ex":{"en":"Can you talk openly about sex with your parents?","cn":"你可以跟父母敞开谈性的问题吗？"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"公开地；公然地；未加隐瞒地；坦率地","en":"If you do something openly, you do it without hiding any facts or hiding your feelings.","ex":{"en":"We can now talk openly about AIDS which we couldn't before","cn":"现在我们能公开谈论以前讳言不提的艾滋病问题。"}}]},"examples":[{"en":"Can you talk openly about sex with your parents?","cn":"你可以跟父母敞开谈性的问题吗？"},{"en":"The men in prison would never cry openly (= so that other people could see).","cn":"狱中犯人从不当众哭泣。"}]},"option":{"media":{"uk":"media/uk/option__gb_1.mp3","us":"media/us/option__us_1.mp3"},"oxford":{"phon":"ˈɒpʃn","pos":"noun","senses":[{"en":"something that you can choose to have or do; the freedom to choose what you do","cn":"可选择的事物；选择；选择权；选择的自由","g":"[countable, uncountable]","ex":{"en":"As I see it, we have two options…","cn":"据我看，我们有两种选择…"}},{"en":"a subject that a student can choose to study, but that they do not have to do","cn":"选修课","g":"[countable]","ex":{"en":"The course offers options in design and computing.","cn":"这一课程开了设计和计算机技术的选修科目。"}},{"en":"the right to buy or sell something at some time in the future","cn":"（未来的）买卖选择权；期权","g":"[countable]","ex":{"en":"share options (= the right to buy shares in a company)","cn":"认股选择权"}},{"en":"one of the choices you can make when using a computer program","cn":"选项；选择","g":"[countable]","lab":"computing","ex":{"en":"Choose the ‘Cut’ option from the Edit menu.","cn":"从编辑菜单上选“剪切”项。"}},{"en":"to buy or sell the right to own or use something at some time in the future","cn":"购买（或出售）…的选择权","ex":{"en":"The novel has been optioned for the screen by his production company.","cn":"这部小说改编成影视作品的权利已经被他的制作公司买下了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"可选择的事物","en":"An option is something that you can choose to do in preference to one or more alternatives.","ex":{"en":"He's argued from the start that America and its allies are putting too much emphasis on the military option","cn":"他从一开始就认为美国及其盟国过于强调军事手段。"}},{"pos":"N-SING 单数名词","cn":"选择；选择权","en":"If you have the option of doing something, you can choose whether to do it or not.","ex":{"en":"Criminals are given the option of going to jail or facing public humiliation","cn":"罪犯可以选择要么坐牢，要么遭受当众羞辱。"}},{"pos":"N-COUNT 可数名词","cn":"（将来的）购买权，出售权；期权","en":"In business, an option is an agreement or contract that gives someone the right to buy or sell something such as property or shares at a future date.","ex":{"en":"Each bank has granted the other an option on 19.9% of its shares.","cn":"两家银行都同意给予对方其19.9%股份的期权。"}},{"pos":"N-COUNT 可数名词","cn":"选修课","en":"An option is one of a number of subjects which a student can choose to study as a part of his or her course.","ex":{"en":"Several options are offered for the student's senior year.","cn":"为毕业班学生开设了几门选修课。"}},{"pos":"PHRASE 短语","cn":"暂不作决定；保留选择权","en":"If you keep your options open or leave your options open, you delay making a decision about something.","ex":{"en":"I am keeping my options open. I have not made a decision on either matter.","cn":"我保留选择权，这两件事我都还没有作出决定。"}},{"pos":"PHRASE 短语","cn":"最容易的选择；最保险的选择","en":"If you take the soft option, you do the thing that is easiest or least likely to cause trouble in a particular situation.","ex":{"en":"We take the soft option. I like to keep the crowd happy because that's what they pay for","cn":"我们决定采取最保险的方案。我希望让观众开心，因为他们就是为这个掏钱的。"}}]},"examples":[{"en":"You can be paid in cash weekly or by cheque monthly: those are the two alternatives.","cn":"你的工资可以按周以现金支取，或按月以支票支取。二者可选其一。"},{"en":"The novel has been optioned for the screen by his production company.","cn":"这部小说改编成影视作品的权利已经被他的制作公司买下了。"}]},"opiate":{"oxford":{"phon":"ˈəʊpiət","pos":"noun","senses":[{"en":"a drug made from opium. Opiates are used in medicine to reduce severe pain.","cn":"阿片制剂"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用于镇痛或安眠的）鸦片制剂","en":"An opiate is a drug that contains opium. Opiates are used to reduce pain or to help people to sleep.","ex":{"en":"One woman suffered such severe pain she had to take opiates to control it.","cn":"有一位妇女剧痛难忍，不得不服用鸦片制剂来镇痛。"}},{"pos":"N-COUNT 可数名词","cn":"（使人忽视重要事情的）麻醉品，慰藉物","en":"If you call something an opiate, you disapprove of it because it makes people think less or spend less time on important activities.","ex":{"en":"...the opiate of mass entertainment","cn":"起到麻痹作用的大众娱乐"}}]},"media":{"uk":"media/uk/opiate__gb_1.mp3","us":"media/us/opiate__us_1.mp3"},"examples":[{"en":"Hollywood movies were seen as an opiate for the people.","cn":"好莱坞影片曾被视为人们的精神鸦片。"}]},"opening":{"media":{"uk":"media/uk/opening__gb_1.mp3","us":"media/us/opening__us_1.mp3"},"oxford":{"phon":"ˈəʊpənɪŋ","pos":"noun","senses":[{"en":"a space or hole that somebody/something can pass through","cn":"孔；洞；缺口","g":"[countable]","ex":{"en":"We could see the stars through an opening in the roof.","cn":"我们从屋顶的小洞能看见星星。"}},{"en":"the beginning or first part of something","cn":"开始；开端","g":"[countable, usually singular]","ex":{"en":"The movie has an exciting opening.","cn":"电影的开头非常刺激。"}},{"en":"a ceremony to celebrate the start of a public event or the first time a new building, road, etc. is used","cn":"开幕式；落成典礼","g":"[countable, usually singular]","ex":{"en":"the official opening of the new hospital","cn":"新建医院的落成典礼"}},{"en":"the act or process of making something open or of becoming open","cn":"开；开放；展开","g":"[countable, uncountable]","ex":{"en":"the opening of a flower","cn":"花朵的绽放"}},{"en":"a job that is available","cn":"空缺的职位","g":"[countable]","ex":{"en":"There are several openings in the sales department.","cn":"销售部有几个空缺。"}},{"en":"a good opportunity for somebody","cn":"良机","g":"[countable]","ex":{"en":"Winning the competition was the opening she needed for her career.","cn":"在这次比赛中获胜是她未来事业发展的良好开端。"}},{"en":"part of a piece of clothing that is made to open and close so that it can be put on easily","cn":"开襟；开口","g":"[countable]","ex":{"en":"The skirt has a side opening.","cn":"这裙子是侧面开衩的。"}},{"en":"first; beginning","cn":"开始的；开篇的；第一","ex":{"en":"his opening remarks","cn":"他的开场白"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开始的;开端的;开场的","en":"The opening event, item, day, or week in a series is the first one.","ex":{"en":"They returned to take part in the season's opening game.","cn":"他们回来参加本赛季的开幕赛。"}},{"pos":"N-COUNT 可数名词","cn":"开始；开端；开场","en":"The opening of something such as a book, play, or concert is the first part of it.","ex":{"en":"The opening of the scene depicts Akhnaten and his family in a moment of intimacy.","cn":"这幕戏的开场描绘了埃及法老阿肯那顿和他的家人其乐融融的情景。"}},{"pos":"N-COUNT 可数名词","cn":"孔；洞；缺口","en":"An opening is a hole or empty space through which things or people can pass.","ex":{"en":"He squeezed through a narrow opening in the fence.","cn":"他从围栏上的狭窄缺口里挤了过去。"}},{"pos":"N-COUNT 可数名词","cn":"（林中）空地","en":"An opening in a forest is a small area where there are no trees or bushes.","ex":{"en":"I glanced down at the beach as we passed an opening in the trees.","cn":"我们经过一块林中空地时，我往下扫了一眼海滩。"}},{"pos":"N-COUNT 可数名词","cn":"有利机会；机遇","en":"An opening is a good opportunity to do something, for example to show people how good you are.","ex":{"en":"Her capabilities were always there; all she needed was an opening to show them.","cn":"她一直都很有能力；她需要的只是一次展示才华的机会。"}},{"pos":"N-COUNT 可数名词","cn":"（职位的）空缺","en":"An opening is a job that is available.","ex":{"en":"We don't have any openings now, but we'll call you if something comes up.","cn":"我们现在没有职位空缺，一旦有的话我们会给你打电话。"}}]},"examples":[{"en":"Winning the competition was the opening she needed for her career.","cn":"在这次比赛中获胜是她未来事业发展的良好开端。"},{"en":"Late opening of supermarkets is common in Britain now.","cn":"现在超市营业至很晚在英国司空见惯。"}],"base":"open"},"operates":{"lemma":"operate"},"opponents":{"lemma":"opponent"},"opal":{"media":{"uk":"media/uk/opal__gb_1.mp3","us":"media/us/opal__us_1.mp3"},"oxford":{"phon":"ˈəʊpl","pos":"noun","senses":[{"en":"a white or almost clear semi-precious stone in which changes of colour are seen, used in jewellery","cn":"欧泊；蛋白石","ex":{"en":"an opal ring","cn":"欧泊戒指"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蛋白石","en":"An opal is a precious stone. Opals are colourless or white, but other colours are reflected in them."}]},"examples":[{"en":"an opal ring","cn":"蛋白石戒指"}]},"operational":{"oxford":{"phon":"ˌɒpəˈreɪʃənl","pos":"adjective","senses":[{"en":"connected with the way in which a business, machine, system, etc. works","cn":"操作的；运转的；运营的；业务的","g":"[usually before noun]","ex":{"en":"operational activities/costs/difficulties","cn":"营运活动／成本／困难"}},{"en":"ready or available to be used","cn":"可使用","g":"[not usually before noun]","ex":{"en":"The new airport is now fully operational.","cn":"新机场现在可全面投入运营。"}},{"en":"connected with a military operation","cn":"军事行动的","g":"[only before noun]","ex":{"en":"operational headquarters","cn":"作战指挥部"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（机器、设备等）正常运转的，可使用的","en":"A machine or piece of equipment that is operational is in use or is ready for use.","ex":{"en":"The whole system will be fully operational by December 1995.","cn":"整个系统到1995年12月将可全面投入使用。"}},{"pos":"ADJ 形容词","cn":"操作上的；实施时的；运行中的","en":"Operational factors or problems relate to the working of a system, device, or plan.","ex":{"en":"The nuclear industry was required to prove that every operational and safety aspect had been fully researched.","cn":"核工业被要求证明其在运营与安全各方面都进行过充分的研究。"}}]},"media":{"uk":"media/uk/operational__gb_1.mp3","us":"media/us/operational__us_1.mp3"},"examples":[{"en":"The new airport is now fully operational.","cn":"新机场现在可全面投入运营。"},{"en":"operational activities/costs/difficulties","cn":"营运上的活动/成本/困难"}]},"opposite":{"media":{"uk":"media/uk/opposite__gb_1.mp3","us":"media/us/opposite__us_1.mp3"},"oxford":{"phon":"ˈɒpəzɪt","pos":"adjective","senses":[{"en":"on the other side of a particular area from somebody/something and usually facing them","cn":"对面的；另一边的","g":"[only before noun]","ex":{"en":"Answers are given on the opposite page.","cn":"答案在对页上。"}},{"en":"facing the speaker or somebody/something that has been mentioned","cn":"对面的","ex":{"en":"I could see smoke coming from the windows of the house directly opposite.","cn":"我能看到烟从正对面的窗户里冒出来。"}},{"en":"as different as possible from something","cn":"相反的；迥然不同的","g":"[usually before noun]","ex":{"en":"I watched them leave and then drove off in the opposite direction.","cn":"我目送他们离开，然后开车向相反的方向驶去。"}},{"en":"a person or thing that is as different as possible from somebody/something else","cn":"对立的人（或物）；对立面；反面","ex":{"en":"Hot and cold are opposites.","cn":"热和冷是对立面。"},"pos":"noun"},{"en":"on the other side of a particular area from somebody/something, and usually facing them","cn":"与…相对；在…对面","ex":{"en":"I sat opposite him during the meal (= on the other side of the table).","cn":"席间我坐在他的对面。"},"pos":"preposition"},{"en":"acting in a film or play as the partner of somebody","cn":"与…合演；与…联袂演出","ex":{"en":"She starred opposite Tom Hanks.","cn":"她与汤姆·汉克斯联袂主演。"},"pos":"preposition"},{"en":"on the other side of a particular area from somebody/something and usually facing them","cn":"对面的；另一边的","ex":{"en":"There's a newly married couple living opposite (= on the other side of the road).","cn":"对面住了一对新婚夫妇。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…的对面","en":"If one thing is opposite another, it is on the other side of a space from it.","ex":{"en":"Jennie had sat opposite her at breakfast.","cn":"珍妮吃早餐时坐在她对面。"}},{"pos":"ADJ 形容词","cn":"另一边的；对面的","en":"The opposite side or part of something is the side or part that is furthest away from you.","ex":{"en":"...the opposite corner of the room.","cn":"房间的对角"}},{"pos":"ADJ 形容词","cn":"（同一类事物）截然相反的，全然不同的","en":"Opposite is used to describe things of the same kind which are completely different in a particular way. For example, north and south are opposite directions, and winning and losing are opposite results in a game.","ex":{"en":"All the cars driving in the opposite direction had their headlights on","cn":"对面开来的车都打着头灯。"}},{"pos":"N-COUNT 可数名词","cn":"对立物；对立面","en":"The opposite of someone or something is the person or thing that is most different from them.","ex":{"en":"Ritter was a very complex man but Marius was the opposite, a simple farmer","cn":"里特城府颇深，而马里厄斯恰恰相反，是个心地淳朴的农民。"}}]},"examples":[{"en":"It's not easy having a relationship when you live at opposite ends of the country.","cn":"人虽同国却各处东西；在这种情况下谈恋爱，谈何容易。"},{"en":"I thought she would be small and blonde but she's the complete opposite.","cn":"我原以为她是一位身材娇小的金发女郎，但她恰恰相反。"}]},"opposed":{"media":{"uk":"media/uk/opposed__gb_1.mp3","us":"media/us/opposed__us_1.mp3"},"oxford":{"phon":"əˈpəʊzd","pos":"adjective","senses":[{"en":"disagreeing strongly with something and trying to stop it","cn":"强烈反对","ex":{"en":"He was strongly opposed to modernism in art.","cn":"他强烈反对艺术中的现代主义。"}},{"en":"very different from something","cn":"截然不同","ex":{"en":"Our views are diametrically opposed on this issue.","cn":"在这个问题上，我们的观点大相径庭。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反对的；不赞成的","en":"If you are opposed to something, you disagree with it or disapprove of it.","ex":{"en":"I am utterly opposed to any form of terrorism","cn":"我坚决反对任何形式的恐怖主义。"}},{"pos":"ADJ 形容词","cn":"对立的；对抗的；相对的；相反的","en":"You say that two ideas or systems are opposed when they are opposite to each other or very different from each other.","ex":{"en":"...people with policies almost diametrically opposed to his own","cn":"提出与他几乎截然相反的政策的人"}},{"pos":"PHRASE 短语","cn":"而不是","en":"You use as opposed to when you want to make it clear that you are talking about one particular thing and not something else.","ex":{"en":"We ate in the restaurant, as opposed to the bistro.","cn":"我们是在餐厅吃的饭，而不是在小饭馆。"}}]},"examples":[{"en":"200 attended, as opposed to 300 the previous year.","cn":"出席的有 200 人，而前一年是 300 人。"},{"en":"This exercise develops suppleness as opposed to (= rather than) strength.","cn":"这项锻炼不是增强力量，而是增强柔韧性的。"}],"base":"oppose"},"optic":{"media":{"uk":"media/uk/optic__gb_1.mp3","us":"media/us/optic__us_1.mp3"},"oxford":{"phon":"ˈɒptɪk","pos":"adjective","senses":[{"en":"connected with the eye or the sense of sight","cn":"眼的；视觉的","ex":{"en":"the optic nerve (= from the eye to the brain)","cn":"视神经"}},{"en":"a device for measuring out exact amounts of strong alcoholic drinks in a bar","cn":"奥普蒂克量杯（酒吧用以量烈性酒）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"眼的；视力的；视觉的","en":"Optic means relating to the eyes or to sight.","ex":{"en":"The reason for this is that the optic nerve is a part of the brain.","cn":"这其中的原因在于视神经是大脑的一部分。"}}]},"examples":[{"en":"the optic nerve (= from the eye to the brain)","cn":"视神经"},{"en":"the optic nerve","cn":"视神经"}]},"optimistic":{"oxford":{"phon":"ˌɒptɪˈmɪstɪk","pos":"adjective","senses":[{"en":"expecting good things to happen or something to be successful; showing this feeling","cn":"乐观的；抱乐观看法的","ex":{"en":"We are now taking a more optimistic view.","cn":"我们现在抱较乐观的态度。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐观的","en":"Someone who is optimistic is hopeful about the future or the success of something in particular.","ex":{"en":"The President says she is optimistic that an agreement can be worked out soon","cn":"总统说她对很快达成协议持乐观态度。"}}]},"media":{"uk":"media/uk/optimistic__gb_1.mp3","us":"media/us/optimistic__us_1.mp3"},"examples":[{"en":"They are cautiously optimistic that the reforms will take place.","cn":"他们对是否实行改革表示审慎的乐观。"},{"en":"She's not very optimistic about the outcome of the talks.","cn":"她对会谈的结果不太乐观。"}]},"optimist":{"oxford":{"phon":"ˈɒptɪmɪst","pos":"noun","senses":[{"en":"a person who always expects good things to happen or things to be successful","cn":"乐观的人；乐天派","ex":{"en":"I'm an eternal optimist—I'm sure things will get better.","cn":"我是一个永远的乐观主义者。我相信情况会变得更好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乐观者","en":"An optimist is someone who is hopeful about the future.","ex":{"en":"Optimists reckon house prices will move up with inflation this year.","cn":"乐观人士认为今年的房价将会随通货膨胀而上涨。"}}]},"media":{"uk":"media/uk/optimist__gb_1.mp3","us":"media/us/optimist__us_1.mp3"},"examples":[{"en":"He’s an eternal optimist (= he always believes that good things will happen ) .","cn":"他是个永远的乐观主义者。"}]},"opinion":{"media":{"uk":"media/uk/opinion__gb_1.mp3","us":"media/us/opinion__us_1.mp3"},"oxford":{"phon":"əˈpɪnjən","pos":"noun","senses":[{"en":"your feelings or thoughts about somebody/something, rather than a fact","cn":"意见；想法；看法","g":"[countable]","lab":"formal","ex":{"en":"He has very strong political opinions.","cn":"他的政见颇为坚定。"}},{"en":"the beliefs or views of a group of people","cn":"（群体的）观点，信仰","g":"[uncountable]","ex":{"en":"legal/medical/political opinion (= the beliefs of people working in the legal, etc. profession)","cn":"法学界／医学界／政界的观点"}},{"en":"advice from a professional person","cn":"专家意见","g":"[countable]","ex":{"en":"The couple sought the opinions of other doctors who confirmed the diagnosis.","cn":"这对夫妇征求了其他确认了这一诊断的医生的意见。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意见；看法；主张；见解","en":"Your opinion about something is what you think or believe about it.","ex":{"en":"I wasn't asking for your opinion, Dick","cn":"我并不是在征求你的意见，迪克。"}},{"pos":"N-SING 单数名词","cn":"（对某人的）评价，印象","en":"Your opinion of someone is your judgment of their character or ability.","ex":{"en":"That improved Mrs Goole's already favourable opinion of him.","cn":"那件事更加深了古尔太太对他的好印象。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"舆论；（群体的）信仰，观点","en":"You can refer to the beliefs or views that people have as opinion .","ex":{"en":"Some, I suppose, might even be in positions to influence opinion","cn":"有的人，我认为，甚至有可能影响舆论。"}},{"pos":"N-COUNT 可数名词","cn":"专家意见；鉴定","en":"An opinion from an expert is the advice or judgment that they give you in the subject that they know a lot about.","ex":{"en":"Even if you have had a regular physical check-up recently, you should still seek a medical opinion.","cn":"即使近期做过一次常规体检，也应当征求医生的意见。"}},{"pos":"PHRASE 短语","cn":"在…看来；据…的意见","en":"You add expressions such as 'in my opinion' or 'in their opinion' to a statement in order to indicate that it is what you or someone else thinks, and is not necessarily a fact.","ex":{"en":"The book is, in Henry's opinion, the best book on the subject","cn":"依照亨利的看法，这本书是关于该主题的最佳著述。"}},{"pos":"PHRASE 短语","cn":"持…观点；认为；相信","en":"If someone is of the opinion that something is the case, that is what they believe.","ex":{"en":"Frank is of the opinion that the 1934 yacht should have won.","cn":"弗兰克认为本该是那艘1934年的帆船获胜。"}},{"pos":"","cn":"","en":"a matter of opinion→see: ;"}]},"examples":[{"en":"If you want my opinion, I think you'd be crazy not to accept.","cn":"既然要我说嘛，我认为你不接受那才傻呢。"},{"en":"There is a difference of opinion (= people disagree) as to the merits of the plan.","cn":"关于这个计划的优缺点，大家意见分歧。"}]},"operating":{"lemma":"operate"},"openings":{"lemma":"open","media":{"uk":"media/uk/opening__gb_1.mp3","us":"media/us/opening__us_1.mp3"}},"opera":{"media":{"uk":"media/uk/opera__gb_1.mp3","us":"media/us/opera__us_1.mp3"},"oxford":{"phon":"ˈɒprə","pos":"noun","senses":[{"en":"a dramatic work in which all or most of the words are sung to music; works of this type as an art form or entertainment","cn":"歌剧；歌剧剧本；歌剧艺术","g":"[countable, uncountable]","ex":{"en":"Puccini’s operas","cn":"普契尼的歌剧"}},{"en":"a company that performs opera; a building in which operas are performed","cn":"歌剧团；歌剧院","g":"[countable]","ex":{"en":"the Vienna State Opera","cn":"维也纳国家歌剧院"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"歌剧","en":"An opera is a play with music in which all the words are sung.","ex":{"en":"...a one-act opera about contemporary women in America.","cn":"关于当代美国女性的独幕歌剧"}}]},"examples":[{"en":"operatic arias/composers","cn":"歌剧咏叹调/作曲家"},{"en":"the Vienna State Opera","cn":"维也纳国家歌剧院"}]},"operation":{"media":{"uk":"media/uk/operation__gb_1.mp3","us":"media/us/operation__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈreɪʃn","pos":"noun","senses":[{"en":"the process of cutting open a part of a person’s body in order to remove or repair a damaged part","cn":"手术","g":"[countable]","lab":"also British English, informal，，","sc":"medical","ex":{"en":"Will I need to have an operation?","cn":"我需要动手术吗？"}},{"en":"an organized activity that involves several people","cn":"（有组织的）活动，行动","g":"[countable]","sc":"organized activity","ex":{"en":"Weather conditions were too bad to mount a rescue operation.","cn":"天气条件太恶劣，无法开展救援行动。"}},{"en":"a business or company, usually one that involves many parts","cn":"（通常有多个部门的）企业，公司","g":"[countable]","sc":"business","ex":{"en":"a huge multinational operation","cn":"庞大的跨国公司"}},{"en":"the activity or work done in a company, or in an area of business or industry","cn":"（企业或工商业）活动，业务","g":"[countable, usually plural]","sc":"business","ex":{"en":"The firm is looking to expand its operations overseas.","cn":"该公司正寻求扩大其海外业务。"}},{"en":"the department in a company that manages the way it produces goods or delivers services and makes sure its business practices are efficient","cn":"公司中负责生产商品或提供服务的方式并确保其业务实践高效的部门","g":"[plural]","lab":"informal","sc":"business","ex":{"en":"He works in operations.","cn":"他从事运营工作。"}},{"en":"an act performed by a machine, especially a computer","cn":"运算；运作","g":"[countable, uncountable]","sc":"computer","ex":{"en":"The whole operation is performed in less than three seconds.","cn":"全部运算在三秒内完成。"}},{"en":"the way that parts of a machine or a system work; the process of making something work","cn":"运转；运行；操作","g":"[uncountable]","sc":"machine/system","ex":{"en":"Regular servicing guarantees the smooth operation of the engine.","cn":"定期维修可保持发动机的顺畅运转。"}},{"en":"the action of functioning; the fact of being used or active or having an effect","cn":"正常工作；运作；使用中；生效","g":"[uncountable]","sc":"machine/system","ex":{"en":"The factory will cease operation at the end of the year.","cn":"工厂将于年底停止运营。"}},{"en":"military activity","cn":"军事行动","g":"[countable, usually plural]","sc":"military activity","ex":{"en":"joint military/combat operations","cn":"联合军事／联合作战行动"}},{"en":"a process in which a number or quantity is changed by adding, multiplying, etc.","cn":"运算","g":"[countable]","sc":"mathematics"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（由大量人员参与、具有高度组织性的）活动，行动，工作","en":"An operation is a highly organized activity that involves many people doing different things.","ex":{"en":"The rescue operation began on Friday afternoon","cn":"救援行动于星期五下午开始。"}},{"pos":"N-COUNT 可数名词","cn":"企业；公司","en":"A business or company can be referred to as an operation .","ex":{"en":"Thorn's electronics operation employs around 5,000 people","cn":"索恩的电子公司雇用了约5,000名员工。"}},{"pos":"N-COUNT 可数名词","cn":"手术","en":"When a patient has an operation, a surgeon cuts open their body in order to remove, replace, or repair a diseased or damaged part.","ex":{"en":"Charles was at the clinic recovering from an operation on his arm.","cn":"查尔斯的胳膊动了手术，正在这家诊所进行康复治疗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"使用；运作","en":"If a system is in operation, it is being used.","ex":{"en":"Until the rail links are in operation, passengers can only travel through the tunnel by coach.","cn":"在铁路连线开通之前，乘客只能乘坐长途客车穿越隧道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（机器、设备等的）运转，运行","en":"If a machine or device is in operation, it is working.","ex":{"en":"There are three ski lifts in operation.","cn":"有3台滑雪缆车在运行。"}},{"pos":"PHRASE 短语","cn":"（使）施行；（使）实行；（使）生效","en":"When a rule, system, or plan comes into operation or you put it into operation, you begin to use it.","ex":{"en":"The Financial Services Act came into operation four years ago","cn":"《金融服务法》于4年前开始实施。"}}]},"examples":[{"en":"The police have launched a major operation against drug suppliers.","cn":"警方展开了一次打击毒贩的大规模行动。"},{"en":"Doctors performed an emergency operation for appendicitis last night.","cn":"医生昨天夜里做了紧急阑尾炎手术。"}]},"opener":{"oxford":{"phon":"ˈəʊpənə(r)","pos":"noun","senses":[{"en":"a tool that is used to open things","cn":"开启的工具","ex":{"en":"a can opener","cn":"罐头起子"}},{"en":"the first in a series of things such as sports games; the first action in an event, a game, etc.","cn":"揭幕赛；开场戏","ex":{"en":"They won the opener 4–2.","cn":"他们以 4:2 赢了揭幕赛。"}},{"en":"either of the two batsmen who start play","cn":"开球员；首位击球员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"开罐器；开瓶器；开启工具","en":"An opener is a tool which is used to open containers such as tins or bottles.","ex":{"en":"...a tin opener.","cn":"开罐器"}}]},"media":{"uk":"media/uk/opener__gb_1.mp3","us":"media/us/opener__us_1.mp3"},"examples":[{"en":"They won the opener 4–2.","cn":"他们以 4:2 赢了揭幕赛。"},{"en":"Jones scored the opener.","cn":"琼斯首先得分。"}]},"oppressed":{"media":{"uk":"media/uk/oppressed__gb_1.mp3","us":"media/us/oppressed__us_1.mp3"},"oxford":{"phon":"əˈprest","pos":"adjective","senses":[{"en":"treated in a cruel and unfair way and not given the same freedom, rights, etc. as other people","cn":"被压迫的；受迫害的","ex":{"en":"oppressed minorities","cn":"被压迫的少数群体"}},{"en":"people who are oppressed","cn":"被压迫者","g":"[plural]","ex":{"en":"His sympathies were always with the poor and the oppressed.","cn":"他始终同情穷人和受压迫者。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受压迫的；受压制的","en":"People who are oppressed are treated cruelly or are prevented from having the same opportunities, freedom, and benefits as others.","ex":{"en":"Before they took power, they felt oppressed by the white English speakers who controlled things","cn":"他们在执政之前感到遭受了那些控制一切的说英语的白人的压迫。"}}]},"examples":[{"en":"oppressed minorities","cn":"被压迫的少数群体"}]},"opposition":{"media":{"uk":"media/uk/opposition__gb_1.mp3","us":"media/us/opposition__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈzɪʃn","pos":"noun","senses":[{"en":"the act of strongly disagreeing with somebody/something, especially with the aim of preventing something from happening","cn":"（强烈的）反对，反抗，对抗","g":"[uncountable, singular]","ex":{"en":"Opposition came primarily from students.","cn":"反对意见主要来自学生。"}},{"en":"the act of competing against somebody in a contest","cn":"（比赛中的）对抗；竞争","g":"[uncountable]","ex":{"en":"She won against determined opposition from last year's champion.","cn":"她顶住了去年冠军的顽强抵抗，获得了胜利。"}},{"en":"the people you are competing against in business, a competition, a game, etc.","cn":"（商业、竞赛、游戏等的）对手，敌手，竞争者","g":"[singular + singular or plural verb]","ex":{"en":"He's gone to work for the opposition.","cn":"他去为竞争对手工作了。"}},{"en":"the main political party that is opposed to the government; the political parties that are in a parliament but are not part of the government","cn":"反对党；在野党","g":"[singular + singular or plural verb]","lab":"North American English","ex":{"en":"the leader of the Opposition","cn":"反对党领袖"}},{"en":"the state of being as different as possible; two things that are as different as possible","cn":"对立；对立的事物","g":"[uncountable, countable]","lab":"formal","ex":{"en":"the opposition between good and evil","cn":"善与恶的对立"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（强烈的）反对，不赞成","en":"Opposition is strong, angry, or violent disagreement and disapproval.","ex":{"en":"The government is facing a new wave of opposition in the form of a student strike","cn":"政府面临着学生通过罢课掀起的新一轮反对浪潮。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（与政府意见相左的）反对党，在野党，反对派","en":"The opposition is the political parties or groups that are opposed to a government.","ex":{"en":"The main opposition parties boycotted the election, saying it would not be conducted fairly.","cn":"主要反对党联合抵制这次选举，认为该选举将缺乏公正性。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（议会或立法机构中的）反对党，在野党，反对派","en":"In a country's parliament or legislature, the opposition refers to the politicians or political parties that form part of the parliament or legislature, but are not the government.","ex":{"en":"...the Leader of the Opposition.","cn":"反对党领袖"}},{"pos":"N-SING-COLL 单数集合名词","cn":"（体育比赛中的）对手，竞争者，竞争队伍","en":"The opposition is the person or team you are competing against in a sports event.","ex":{"en":"Poland provide the opposition for the Scots' last warm-up match at home.","cn":"苏格兰队在国内最后一场热身赛的对手是波兰队。"}}]},"examples":[{"en":"Liverpool couldn't match the opposition in the final and lost 2–0.","cn":"利物浦队在决赛中不敌对手，以 0:2 输掉比赛。"},{"en":"He spent five years in prison for his opposition to the regime.","cn":"他因为反对那个政权而过了五年的铁窗生活。"}]},"opaque":{"media":{"uk":"media/uk/opaque__gb_1.mp3","us":"media/us/opaque__us_1.mp3"},"oxford":{"phon":"əʊˈpeɪk","pos":"adjective","senses":[{"en":"not clear enough to see through or allow light through","cn":"不透明的；不透光的；浑浊的","ex":{"en":"opaque glass","cn":"不透明的玻璃"}},{"en":"difficult to understand; not clear","cn":"难懂；模糊；隐晦；不清楚","ex":{"en":"The jargon in his talk was opaque to me.","cn":"他谈话中使用的行话对我是一团迷雾。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不透明的;不透光的","en":"If an object or substance is opaque, you cannot see through it.","ex":{"en":"You can always use opaque glass if you need to block a street view.","cn":"如果不想从室内看到街景，可以使用不透明玻璃。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费解的；难懂的；晦涩的","en":"If you say that something is opaque, you mean that it is difficult to understand.","ex":{"en":"...the opaque language of the inspector's reports.","cn":"巡视员报告中晦涩难懂的语言"}}]},"examples":[{"en":"The jargon in his talk was opaque to me.","cn":"他谈话中使用的行话对我是一团迷雾。"},{"en":"opaque tights","cn":"不透明的连裤袜"}]},"oppression":{"media":{"uk":"media/uk/oppression__gb_1.mp3","us":"media/us/oppression__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"压迫；压制","en":"Oppression is the cruel or unfair treatment of a group of people.","ex":{"en":"...an attempt to escape political oppression.","cn":"企图逃避政治压迫的努力"}}]},"examples":[{"en":"victims of oppression","cn":"受压迫者"}],"oxford":{"phon":"əˈpreʃn","pos":"noun","senses":[{"en":"cruel and unfair treatment of people, especially by not giving them the same freedom, rights, etc. as other people","cn":"压迫；欺压；压制","ex":{"en":"victims of oppression","cn":"受压迫者"}}]}},"optics":{"oxford":{"phon":"ˈɒptɪks","pos":"noun","senses":[{"en":"the scientific study of sight and light","cn":"光学"},{"en":"the way in which an action or event is seen and understood by the public","cn":"公众认知","g":"[plural]","lab":"especially North American English","ex":{"en":"In politics, optics matter.","cn":"在政治上，公众认知很重要。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"光学","en":"Optics is the branch of science concerned with vision, sight, and light."}]},"media":{"uk":"media/uk/optics__gb_1.mp3","us":"media/us/optics__us_1.mp3"},"examples":[{"en":"Optics is a branch of physics.","cn":""}],"base":"optic"},"opportunity":{"media":{"uk":"media/uk/opportunity__gb_1.mp3","us":"media/us/opportunity__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈtjuːnəti","pos":"noun","senses":[{"en":"a time when a particular situation makes it possible to do or achieve something","cn":"机会；时机","ex":{"en":"Don't miss this opportunity!","cn":"勿失良机！"}},{"en":"the third Mars Rover vehicle which landed on the planet Mars in 2004 and sent pictures of the planet back to NASA","cn":"机会：第三辆火星探测器车于2004年降落在火星上并将该行星的照片发送回了NASA","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"机会；时机","en":"An opportunity is a situation in which it is possible for you to do something that you want to do.","ex":{"en":"I had an opportunity to go to New York and study","cn":"我曾经有一个去纽约学习的机会。"}}]},"examples":[{"en":"At least give him the opportunity of explaining what happened.","cn":"至少要给他机会解释一下发生了什么事。"},{"en":"You'll have the opportunity to ask any questions at the end.","cn":"你们最后将有机会提问任何问题。"}]},"open":{"media":{"uk":"media/uk/open__gb_1.mp3","us":"media/us/open__us_1.mp3"},"oxford":{"phon":"ˈəʊpən","pos":"adjective","senses":[{"en":"allowing things or people to go through; not closed or blocked","cn":"开放的；敞开的","sc":"not closed","ex":{"en":"A wasp flew in the open window.","cn":"一只黄蜂飞进了开着的窗子。"}},{"en":"with eyelids or lips apart","cn":"张开的；张着的","sc":"not closed","ex":{"en":"She had difficulty keeping her eyes open (= because she was very tired).","cn":"她连睁开眼睛的力气都没有了。"}},{"en":"spread out; with the edges apart","cn":"展开的；开放的","sc":"not closed","ex":{"en":"The flowers are all open now.","cn":"花现在都开了。"}},{"en":"not fastened or covered, so that things can easily come out or be put in","cn":"敞口的；未封的","sc":"not fastened","ex":{"en":"Leave the envelope open.","cn":"别封上信封。"}},{"en":"not fastened","cn":"未系着","sc":"not fastened","ex":{"en":"Her coat was open.","cn":"她的外衣敞着。"}},{"en":"not surrounded by anything; not closed in","cn":"开阔的；未围上的","sc":"not enclosed","ex":{"en":"open country/countryside (= without forests, buildings, etc.)","cn":"空旷的田野"}},{"en":"with no cover or roof on","cn":"敞开的；露天的；裸露的","lab":"North American English","sc":"not covered","ex":{"en":"an open drain","cn":"一条明沟"}},{"en":"if a shop, bank, business, etc. is open, it is ready for business and will allow customers or visitors to come in","cn":"开放；营业中","g":"[not usually before noun]","sc":"for customers/visitors","ex":{"en":"Is the museum open on Sundays?","cn":"博物馆每星期天都开放吗？"}},{"en":"if a competition, meeting, etc. is open, anyone can enter, attend it, etc.","cn":"对大众开放的；公开的；人人可以参加的","sc":"of competition/building","ex":{"en":"an open debate/championship/scholarship","cn":"公开的辩论会；人人可以参加的锦标赛；人人均可申请的奖学金"}},{"en":"if a competition, building, etc. is open to particular people, those people can enter it","cn":"（比赛、建筑物等）对特定群体开放","g":"[not before noun]","sc":"of competition/building","ex":{"en":"The competition is open to young people under the age of 18.","cn":"这项比赛的参赛对象是 18 岁以下的青少年。"}},{"en":"to be available and ready to use","cn":"可得到；可使用","g":"[not before noun]","sc":"available","ex":{"en":"Is the offer still open?","cn":"这个报价还有效吗？"}},{"en":"if a phone line or other channel of communication is open, it is ready to take calls, receive requests, etc.","cn":"（电话线或其他沟通渠道）开放，畅通","g":"[not before noun]","sc":"available","ex":{"en":"Lines are open 8 am to 7 pm weekdays.","cn":"电话线路的开放时间是工作日的上午 8 点至晚上 7 点。"}},{"en":"likely to suffer something such as criticism, injury, etc.","cn":"易受损害；脆弱","sc":"not protected","ex":{"en":"The system is open to abuse.","cn":"这项制度容易被滥用。"}},{"en":"known to everyone; not kept hidden","cn":"人人皆知的；不保密的；公开的","sc":"not hidden","ex":{"en":"an open quarrel","cn":"公开的争吵"}},{"en":"honest; not keeping thoughts and feelings hidden","cn":"诚恳；坦诚；直率","sc":"honest","ex":{"en":"a frank and open discussion","cn":"开诚布公的讨论"}},{"en":"willing to listen to and think about new ideas","cn":"思想开明的；不固执己见的","sc":"honest","ex":{"en":"He was in an open frame of mind.","cn":"他思想开明。"}},{"en":"not yet finally decided or settled","cn":"未决定的；待决定的","sc":"not yet decided","ex":{"en":"The race is still wide open (= anyone could win).","cn":"赛跑胜负未定。"}},{"en":"allowing something; making something possible","cn":"允许的；留有余地的","sc":"making something possible","ex":{"en":"The price is not open to negotiation.","cn":"价格不容商议。"}},{"en":"that does not have to be used on a particular day","cn":"（使用）日期未定的；不定日期的","sc":"ticket","ex":{"en":"I have an open ticket, so I can travel any day I like.","cn":"我有一张不定日期机票，所以我可以随便哪天去旅行。"}},{"en":"with wide spaces between the threads","cn":"稀疏的；不密的","sc":"cloth","ex":{"en":"an open weave","cn":"稀疏织法"}},{"en":"produced with the tongue in the lowest possible position","cn":"开的；舌位低的","sc":"phonetics"},{"en":"to move a door, window, lid, etc. into a position that is no longer closed; to get into this position","cn":"开；打开；开启","g":"[transitive, intransitive]","sc":"door/window/lid","ex":{"en":"Mr Chen opened the car door for his wife.","cn":"陈先生为妻子打开车门。"},"pos":"verb"},{"en":"to remove or undo the top, cover, etc. of a container or package in order to see or get what is inside","cn":"打开，开启（瓶盖、封口等）","g":"[transitive]","sc":"container/package","ex":{"en":"Shall I open another bottle?","cn":"要不要我再开一瓶？"},"pos":"verb"},{"en":"if you open your eyes or your eyes open, you move your eyelids upwards so that you can see","cn":"睁开","g":"[transitive, intransitive]","sc":"eyes","ex":{"en":"When I opened my eyes a nurse was standing over me.","cn":"当我睁开眼睛时，一名护士站在我身边。"},"pos":"verb"},{"en":"if you open your mouth or your mouth opens, you move your lips, for example in order to speak","cn":"张开","g":"[transitive, intransitive]","sc":"mouth","ex":{"en":"He hardly ever opens his mouth (= speaks).","cn":"他几乎从不开口。"},"pos":"verb"},{"en":"to turn the cover or the pages of a book, newspaper, etc. so that it is no longer closed","cn":"打开；翻开","g":"[transitive]","sc":"book","ex":{"en":"Open your books at page 25.","cn":"把书翻到第 25 页。"},"pos":"verb"},{"en":"to start a computer program or file so that you can use it on the screen; to become available on a computer screen","cn":"启动，打开（计算机程序或文件）；（计算机程序等）开启","g":"[transitive, intransitive]","sc":"computing","ex":{"en":"Open the camera app and tap ‘Options’.","cn":"打开相机应用程序并点击“选项”。"},"pos":"verb"},{"en":"to spread out or unfold; to spread something out or unfold it","cn":"展开；打开","g":"[intransitive, transitive]","sc":"spread out","ex":{"en":"What if the parachute doesn't open?","cn":"降落伞打不开怎么办？"},"pos":"verb"},{"en":"to make it possible for people, cars, goods, etc. to pass through a place","cn":"让（行人、车辆、货物等）通行；开放","g":"[transitive]","sc":"border/road","ex":{"en":"When did the country open its borders?","cn":"这个国家是何时开放边界的？"},"pos":"verb"},{"en":"to start business for the day; to start business for the first time","cn":"开始营业；开业；开门","g":"[intransitive, transitive]","sc":"for customers/visitors","ex":{"en":"What time does the bank open?","cn":"这家银行什么时候开门？"},"pos":"verb"},{"en":"to be ready for people to go to","cn":"开始接待","g":"[intransitive]","sc":"for customers/visitors","ex":{"en":"The new hospital opens on July 1st.","cn":"这家新医院七月一日开诊。"},"pos":"verb"},{"en":"to start an activity or event; to begin using or doing something","cn":"开始进行；着手做","g":"[transitive]","lab":"British English","sc":"start something","ex":{"en":"You need just one pound to open an account with us.","cn":"你只需一英镑就可在我行开立一个账户。"},"pos":"verb"},{"en":"to start in a particular way; to make something start in a particular way","cn":"以…开篇；以…开头","g":"[intransitive, transitive]","sc":"start something","ex":{"en":"How does the play open?","cn":"这部剧怎么开场呢？"},"pos":"verb"},{"en":"to perform a ceremony showing that a building can start being used","cn":"为（建筑物）揭幕；宣布启用","g":"[transitive]","sc":"with ceremony","ex":{"en":"The Queen officially opened the bridge in March.","cn":"女王在三月为大桥开通揭幕。"},"pos":"verb"},{"en":"to make it possible to reach, have, use or do something","cn":"开放；使可以达到（或取得、使用等）","sc":"make something possible","ex":{"en":"This decision opens the possibility of a fresh election.","cn":"这一决定使新一轮选举成为可能。"},"pos":"verb"},{"en":"outdoors; the countryside","cn":"户外；野外；旷野","sc":"outdoors","ex":{"en":"Children need to play out in the open.","cn":"孩子需要在户外玩耍。"},"pos":"noun"},{"en":"not hidden or secret","cn":"公开；非秘密","sc":"not hidden","ex":{"en":"Government officials do not want these comments in the open.","cn":"政府官员不想公开这些评论。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"打开（门、窗、盖等）","en":"If you open something such as a door, window, or lid, or if it opens, its position is changed so that it no longer covers a hole or gap.","ex":{"en":"He opened the window and looked out","cn":"他打开窗户往外看。"}},{"pos":"VERB 动词","cn":"将（瓶、盒等）开封；拆开（包裹、信封等）","en":"If you open something such as a bottle, box, parcel, or envelope, you move, remove, or cut part of it so you can take out what is inside.","ex":{"en":"The Inspector opened the packet of cigarettes","cn":"检查员撕开了那包香烟。"}},{"pos":"V-ERG 及物/不及物动词","cn":"翻开；张开；展开","en":"If you open something such as a book, an umbrella, or your hand, or if it opens, the different parts of it move away from each other so that the inside of it can be seen.","ex":{"en":"He opened the heavy Bible","cn":"他翻开那本厚厚的《圣经》。"}},{"pos":"VERB 动词","cn":"打开（计算机文件）","en":"If you open a computer file, you give the computer an instruction to display it on the screen.","ex":{"en":"Double click on the icon to open the file.","cn":"双击图标打开文件。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使)(眼睛）睁开","en":"When you open your eyes or your eyes open, you move your eyelids upwards, for example when you wake up, so that you can see.","ex":{"en":"When I opened my eyes I saw a man with an axe standing at the end of my bed","cn":"我睁开眼睛时，看见一个手持斧头的男人站在床尾。"}},{"pos":"VERB 动词","cn":"敞开（双臂）","en":"If you open your arms, you stretch them wide apart in front of you, usually in order to put them round someone.","ex":{"en":"She opened her arms and gave me a big hug.","cn":"她张开双臂，紧紧地拥抱了我。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（身前）无遮挡的；（姿势）端正的","en":"If you stand or sit in an open way, the front of your body is fully exposed and you are not bending forward or at an angle to someone.","ex":{"en":"Good listeners even sit in an open way: relaxed, arms loose","cn":"善于倾听的人甚至坐姿也很坦荡端正：身体放松，双臂自然下垂。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦率的；诚恳的；不作伪的","en":"If you describe a person or their character as open, you mean they are honest and do not want or try to hide anything or to deceive anyone.","ex":{"en":"He had always been open with her and she always felt she would know if he lied","cn":"他对她总是坦诚相待，她也一直觉得如果他说谎，自己一定能察觉。"}},{"pos":"ADJ 形容词","cn":"公开的；不加掩饰的","en":"If you describe a situation, attitude, or way of behaving as open, you mean it is not kept hidden or secret.","ex":{"en":"The action is an open violation of the Vienna Convention","cn":"该行为公然违背了《维也纳公约》。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愿意接受（建议、观点等）的；虚怀若谷的","en":"If you are open to suggestions or ideas, you are ready and willing to consider or accept them.","ex":{"en":"They are open to suggestions on how working conditions might be improved.","cn":"他们愿意就如何改善工作条件听取各种意见。"}},{"pos":"ADJ 形容词","cn":"容易招致（滥用、批评等）的；易受（攻击）的","en":"If you say that a system, person, or idea is open to something such as abuse or criticism, you mean they might receive abuse or criticism because of their qualities, effects, or actions.","ex":{"en":"The system, though well-meaning, is open to abuse","cn":"该制度动机虽好，却易遭滥用。"}},{"pos":"ADJ 形容词","cn":"悬而未决的；尚未决定的","en":"If you say that a fact or question is open to debate, interpretation, or discussion, you mean that people are uncertain whether it is true, what it means, or what the answer is.","ex":{"en":"The truth of the facts produced may be open to doubt","cn":"所摆出事实的真实性仍然值得怀疑。"}},{"pos":"V-ERG 及物/不及物动词","cn":"开放（被封的道路、边界等）；开通","en":"If people open something such as a blocked road or a border, or if it opens, people can then pass along it or through it.","ex":{"en":"The rebels have opened the road from Monrovia to the Ivory Coast","cn":"叛乱分子已经开放了从蒙罗维亚到象牙海岸的道路。"}},{"pos":"VERB 动词","cn":"通向（更大的地方）","en":"If a place opens into another, larger place, you can move from one directly into the other.","ex":{"en":"The corridor opened into a low smoky room.","cn":"这条走廊通向一间烟雾弥漫的低矮房间。"}},{"pos":"ADJ 形容词","cn":"开阔的；空旷的","en":"An open area is a large area that does not have many buildings or trees in it.","ex":{"en":"Officers will also continue their search of nearby open ground.","cn":"警察还将继续在附近的开阔地带搜寻。"}},{"pos":"ADJ 形容词","cn":"敞开的；无遮盖的；无围挡的","en":"An open structure or object is not covered or enclosed.","ex":{"en":"Don't leave a child alone in a room with an open fire.","cn":"房间里有裸露的明火时，不要让孩子独处其中。"}},{"pos":"ADJ 形容词","cn":"（伤口）外露的，裸露的，流血的","en":"An open wound is one from which a liquid such as blood is coming."},{"pos":"VERB 动词","cn":"把（衣服）解开；把…的拉链拉开","en":"If you open your shirt or coat, you undo the buttons or pull down the zip.","ex":{"en":"I opened my coat and let him see the belt.","cn":"我解开外衣，让他看那条皮带。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）开始营业；（使）开门","en":"When a shop, office, or public building opens or is opened, its doors are unlocked and the public can go in.","ex":{"en":"Banks closed on Friday afternoon and did not open again until Monday morning.","cn":"银行星期五下午关门，直到星期一上午才营业。"}},{"pos":"V-ERG 及物/不及物动词","cn":"为（大楼、工厂、公司等）举行揭幕典礼；开设；开办；开张","en":"When a public building, factory, or company opens or when someone opens it, it starts operating for the first time.","ex":{"en":"The original station opened in 1754","cn":"最初的车站于1754年落成。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（会议、会谈）开始；召开","en":"If something such as a meeting or series of talks opens, or if someone opens it, it begins.","ex":{"en":"...an emergency session of the Russian Parliament due to open later this morning","cn":"将于今天上午晚些时候召开的俄罗斯议会紧急会议"}},{"pos":"V-ERG及物/不及物动词","cn":"（以…）开始","en":"If an event such as a meeting or discussion opens with a particular activity or if a particular activity opens an event, that activity is the first thing that happens or is dealt with. You can also say that someone such as a speaker or singer opens by doing a particular thing.","ex":{"en":"The service opened with a hymn","cn":"礼拜仪式从唱圣歌开始。"}},{"pos":"VERB 动词","cn":"（股市）开盘，开市","en":"On the stock exchange, the price at which currencies, shares, or commodities open is their value at the start of that day's trading.","ex":{"en":"Gold declined $2 in Zurich to open at 385.50","cn":"苏黎世的金价下挫2美元，以385.50元开盘。"}},{"pos":"VERB 动词","cn":"上映；开演；开幕","en":"When a film, play, or other public event opens, it begins to be shown, be performed, or take place for a limited period of time.","ex":{"en":"A photographic exhibition opens at the Royal College of Art on Wednesday","cn":"星期三一个摄影展在皇家艺术学院开幕。"}},{"pos":"VERB 动词","cn":"（在银行等处）开立（账户）","en":"If you open an account with a bank or a commercial organization, you begin to use their services.","ex":{"en":"He tried to open an account at the branch of his bank nearest to his workplace.","cn":"他想在自己银行离工作单位最近的网点开一个账户。"}},{"pos":"ADJ 形容词","cn":"（机会、选择等）可利用的，可得到的","en":"If an opportunity or choice is open to you, you are able to do a particular thing if you choose to.","ex":{"en":"There are a wide range of career opportunities open to young people.","cn":"年轻人有各种职业选择机会。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（机会、可能性等）出现;（使）产生","en":"To open opportunities or possibilities means the same as to open them up.","ex":{"en":"The chief of naval operations wants to open opportunities for women in the Navy","cn":"美国海军作战部长希望能为女兵提供机会。"}},{"pos":"ADJ 形容词","cn":"人人可以参加（或接受）的；开放的","en":"You can use open to describe something that anyone is allowed to take part in or accept.","ex":{"en":"A recent open meeting of College members revealed widespread dissatisfaction","cn":"最近的一次学会成员公开会上，大家普遍流露出不满情绪。"}},{"pos":"ADJ 形容词","cn":"（提议等）有效的；（职位等）空缺的，可申请的","en":"If something such as an offer or job is open, it is available for someone to accept or apply for.","ex":{"en":"The offer will remain open until further notice.","cn":"该提议仍然有效，直到另行通知。"}},{"pos":"PHRASE 短语","cn":"在露天；在户外；在野外","en":"If you do something in the open, you do it out of doors rather than in a house or other building.","ex":{"en":"Many are sleeping in the open because they have no shelter.","cn":"很多人因为没有栖身之所，只好露宿在外。"}},{"pos":"PHRASE 短语","cn":"公开的；众人皆知的","en":"If an attitude or situation is in the open or out in the open, people know about it and it is no longer kept secret.","ex":{"en":"The medical service had advised us to keep it a secret, but we wanted it in the open.","cn":"这家医疗机构建议我们保密，而我们却想公开此事。"}},{"pos":"PHRASE 短语","cn":"大开的；敞开的；（眼睛）睁大的","en":"If something is wide open, it is open to its full extent.","ex":{"en":"The child had left the inner door wide open.","cn":"这个孩子将里面的门大敞着。"}},{"pos":"PHRASE 短语","cn":"（比赛、选举等）结果不确定的，胜负难定的","en":"If you say that a competition, race, or election is wide open, you mean that anyone could win it, because there is no competitor who seems to be much better than the others.","ex":{"en":"The competition has been thrown wide open by the absence of the world champion.","cn":"由于世界冠军缺阵，这场比赛变得胜负难定。"}},{"pos":"","cn":"","en":"with open arms→see: ; to open the door→see: ; to keep your eyes open→see: ; with your eyes open→see: ; to open your eyes→see: ; to open fire→see: ; to open your heart→see: ; the heavens open→see: ; an open mind→see: ; to open your mind→see: ; to keep your options open→see: ;"},{"pos":"","cn":"","en":"相关词组：open out open up"}]},"examples":[{"en":"It helps to discuss your problems but I find it hard to open up.","cn":"与人谈谈自己面对的问题固然有益，但我觉得有些话很难说得出口。"},{"en":"The road will be opened again in a few hours after police have cleared it.","cn":"待警察清理完以后，道路在几小时内就会重新开放。"}]},"opponent":{"oxford":{"phon":"əˈpəʊnənt","pos":"noun","senses":[{"en":"a person that you are playing or fighting against in a game, competition, argument, etc.","cn":"对手；竞争者","ex":{"en":"a political opponent","cn":"政敌"}},{"en":"a person who is against something and tries to change or stop it","cn":"反对者；阻止者","ex":{"en":"opponents of abortion","cn":"反对堕胎的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（政治上的）对手，敌手","en":"A politician's opponents are other politicians who belong to a different party or who have different aims or policies.","ex":{"en":"...Mr Kennedy's opponent in the leadership contest","cn":"与肯尼迪先生争夺领导权的对手"}},{"pos":"N-COUNT 可数名词","cn":"（体育竞赛中的）对手，竞争者","en":"In a sporting contest, your opponent is the person who is playing against you.","ex":{"en":"Norris twice knocked down his opponent in the early rounds of the fight","cn":"诺里斯在前几个回合中两次击倒对手。"}},{"pos":"N-COUNT 可数名词","cn":"（观点、政策等的）反对者","en":"The opponents of an idea or policy do not agree with it and do not want it to be carried out.","ex":{"en":"...opponents of the spread of nuclear weapons","cn":"反对核武器扩散的人士"}}]},"media":{"uk":"media/uk/opponent__gb_1.mp3","us":"media/us/opponent__us_1.mp3"},"examples":[{"en":"The team's opponents are unbeaten so far this season.","cn":"该队的竞争对手本赛季尚无败绩。"},{"en":"a dangerous/worthy/formidable opponent","cn":"危险的/可敬的/强大的对手"}]},"operated":{"lemma":"operate"},"optimum":{"oxford":{"phon":"ˈɒptɪməm","pos":"adjective","senses":[{"en":"the best possible; producing the best possible results","cn":"最佳的；最适宜的","ex":{"en":"the optimum use of resources","cn":"对资源的充分利用"}},{"en":"the best possible result, set of conditions, etc.","cn":"最佳结果；最好的条件","g":"[singular]","ex":{"en":"For efficient fuel consumption a speed of 60 mph is about the optimum.","cn":"时速60英里节油效果大致最佳。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最优的；最佳的；最适宜的","en":"The optimum or optimal level or state of something is the best level or state that it could achieve.","ex":{"en":"Aim to do some physical activity three times a week for optimum health.","cn":"为了达到最佳的健康状况，要力争每周进行3次身体锻炼。"}}]},"media":{"uk":"media/uk/optimum__gb_1.mp3","us":"media/us/optimum__us_1.mp3"},"examples":[{"en":"the optimum conditions for effective learning","cn":"保证学习效果的最佳条件"},{"en":"the optimum use of resources","cn":"对资源的充分利用"}]},"oppose":{"media":{"uk":"media/uk/oppose__gb_1.mp3","us":"media/us/oppose__us_1.mp3"},"oxford":{"phon":"əˈpəʊz","pos":"verb","senses":[{"en":"to disagree strongly with somebody’s plan, policy, etc. and try to change it or prevent it from succeeding","cn":"反对（计划、政策等）；抵制；阻挠","ex":{"en":"This party would bitterly oppose the re-introduction of the death penalty.","cn":"该党会强烈反对恢复死刑。"}},{"en":"to compete with somebody in a contest","cn":"（在竞赛中）与…对垒，与…角逐","ex":{"en":"He intends to oppose the prime minister in the leadership election.","cn":"在领导层选举中，他欲与首相一决高下。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"反对；阻挠","en":"If you oppose someone or oppose their plans or ideas, you disagree with what they want to do and try to prevent them from doing it.","ex":{"en":"Mr Taylor was not bitter towards those who had opposed him","cn":"泰勒先生对那些曾反对过他的人并未怀恨在心。"}}]},"examples":[{"en":"He intends to oppose the prime minister in the leadership election.","cn":"在领导层选举中，他欲与首相一决高下。"},{"en":"He threw all those that opposed him into prison.","cn":"他把所有反对他的人都投进了监狱。"}]},"options":{"lemma":"option"},"opens":{"lemma":"open"},"operas":{"lemma":"opera"},"operations":{"lemma":"operation"},"opened":{"lemma":"open"},"opposites":{"lemma":"opposite"},"oppressors":{"oxford":{"phon":"əˈpresə(r)","pos":"noun","senses":[{"en":"a person or group of people that treats sb in a cruel and unfair way, especially by not giving them the same rights, etc. as other people","cn":"压迫者；残暴的统治者；暴君"}]}},"opted":{"oxford":{"phon":"ɒpt","pos":"verb","senses":[{"en":"to choose to take or not to take a particular course of action","cn":"选择；挑选"},{"en":"to choose to be part of a system or an agreement","cn":"决定加入；选择参与"}]}},"operators":{"lemma":"operator"},"opinions":{"lemma":"opinion"},"opportunities":{"lemma":"opportunity"},"operator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电话接线员","en":"An operator is a person who connects telephone calls at a telephone exchange or in a place such as an office or hotel.","ex":{"en":"He dialled the operator and put in a call for Rome.","cn":"他拨了接线员的号，让他接通一个到罗马的电话。"}},{"pos":"N-COUNT 可数名词","cn":"（机器）操作员，技工","en":"An operator is a person who is employed to operate or control a machine.","ex":{"en":"...computer operators.","cn":"计算机操作员"}},{"pos":"N-COUNT 可数名词","cn":"（企业的）经营者；运营公司","en":"An operator is a person or a company that runs a business.","ex":{"en":"...'Tele-Communications', the nation's largest cable TV operator.","cn":"全国最大的有线电视运营商“电视通信公司”"}},{"pos":"N-COUNT 可数名词","cn":"精明圆滑的人；善于取巧的人","en":"If you call someone a good operator, you mean that they are skilful at achieving what they want, often in a slightly dishonest way.","ex":{"en":"He was a smart operator. Don't underestimate him.","cn":"他这个人精明圆滑，可别小瞧了他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works on a telephone switchboard , who you can call for help","cn":"电话接线员"},{"en":"someone who operates a machine or piece of equipment 〔","cn":"机器或设备的〕操作者﹐操作员"},{"en":"a person or company that operates a particular business","cn":"经营者﹔公司"}]},"collocations":{"phrases":["ADJ. switchboard, telephone","OPERATOR + VERB connect sb, put sb through I asked the operator to put me through to her office. 2 person who works a machine, etc.","ADJ. experienced, skilled | unskilled | machine, plant | computer, lathe, radio, word processor, etc. 3 person/company that does particular ","ADJ. big, small | private | holiday, tour, travel | cable (television), satellite, telecommunications, etc. | airline, bus, coach, ferry 4 s","ADJ. shrewd, slick, smooth"]},"media":{"uk":"media/ldoce/hwd/bre/5/operator0205.mp3","us":"media/ldoce/hwd/ame/e/operator.mp3"},"examples":[{"en":"a smooth/slick/shrewd operator","cn":"一个八面玲珑/油嘴滑舌/工于心计的取巧者"},{"en":"a computer/machine operator","cn":"电脑/机器操作员"}],"oxford":{"phon":"ˈɒpəreɪtə(r)","pos":"noun","senses":[{"en":"a person who operates equipment or a machine","cn":"操作人员；技工","ex":{"en":"a computer/machine operator","cn":"电脑／机器操作员"}},{"en":"a person or company that runs a particular business","cn":"（某企业的）经营者，专业公司","ex":{"en":"a tour operator","cn":"经营旅游业者"}},{"en":"a person who works on the phone switchboard of a large company or organization, especially at a telephone exchange","cn":"电话员；接线员","lab":"British English, old-fashioned，，","ex":{"en":"Dial 100 and ask for the operator.","cn":"拨 100 找接线员。"}},{"en":"a person who shows skill at getting what they want, especially when this involves behaving in a dishonest way","cn":"投机取巧者；善于钻营的人；骗子","lab":"informal, especially disapproving，，","ex":{"en":"a smooth/slick/shrewd operator","cn":"一个八面玲珑／油嘴滑舌／工于心计的取巧者"}},{"en":"a symbol or function which represents an operation in mathematics","cn":"算子","lab":"mathematics"}]}},"opium":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鸦片","en":"Opium is a powerful drug made from the juice or sap of a type of poppy. Opium is used in medicines that relieve pain or help someone sleep."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a powerful illegal drug made from poppy seeds. Drugs made from opium are used to reduce severe pain.","cn":"鸦片"}]},"collocations":{"phrases":["VERB + OPIUM smoke","OPIUM + NOUN poppy | den • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeopium.mp3","us":"media/ldoce/hwd/ame/5/opium.mp3"},"oxford":{"phon":"ˈəʊpiəm","pos":"noun","senses":[{"en":"a powerful drug made from the juice of a type of poppy (= a kind of flower), used in the past in medicines to reduce pain and help people sleep. Some people take opium illegally for pleasure and can become addicted to it.","cn":"鸦片","ex":{"en":"opium poppies","cn":"罂粟"}}]}},"operative":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"运作（或运转）着的；起作用的；产生影响的","en":"A system or service that is operative is working or having an effect.","ex":{"en":"The commercial telephone service was no longer operative","cn":"商业电话服务已不再运营。"}},{"pos":"N-COUNT 可数名词","cn":"工人；（尤指）技工，操作员","en":"An operative is a worker, especially one who does work with their hands.","ex":{"en":"In an automated car plant there is not a human operative to be seen.","cn":"在自动化汽车制造厂看不到一个工人。"}},{"pos":"N-COUNT 可数名词","cn":"特工；间谍；密探；情报人员","en":"An operative is someone who works for a government agency such as the intelligence service.","ex":{"en":"Naturally the CIA wants to protect its operatives.","cn":"美国中央情报局当然想保护其特工。"}},{"pos":"PHRASE 短语","cn":"关键词","en":"If you describe a word as the operative word, you want to draw attention to it because you think it is important or exactly true in a particular situation.","ex":{"en":"As long as the operative word is 'greed', you can't count on people keeping the costs down","cn":"只要“贪婪”仍是一切的出发点，就别指望人们会降低成本。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"working and able to be used","cn":"运作中的﹐工作着的﹔可使用的"},{"en":"used when you repeat a word from a previous sentence to draw attention to its importance","cn":"最重要的词﹐关键词〔用于重复前一句中的某个词﹐使人注意其重要性〕"},{"en":"relating to a medical operation","cn":"与医疗手术有关的"}]},"vocab":{"pos":"1 adj 2 adj 3 n","senses":[{"en":"Bond, James Bond, is perhaps the most famous fictional operative of our time. Martini-drinking, globe-trotting, and womanizing aside, let us not forget his primary role as a government secret agent — collecting intelligence and bringing down the world's enemies."}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. fully The new system will not become fully operative until next year."]},"media":{"uk":"media/ldoce/hwd/bre/d/operative_n0205.mp3","us":"media/ldoce/hwd/ame/f/operative1.mp3"},"examples":[{"en":"I was in love with her — ‘was’ being the operative word.","cn":"在 I was in love with her 这句话中，was 是关键词。"},{"en":"The station will be fully operative again in January.","cn":"该站将于一月份全部恢复运营。"}],"oxford":{"phon":"ˈɒpərətɪv","pos":"noun","senses":[{"en":"a worker, especially one who works with their hands","cn":"工作人员；（尤指）技术工人，操作员","lab":"specialist","ex":{"en":"a factory operative","cn":"工厂工人"}},{"en":"a person who does secret work, especially for a government organization","cn":"密探；（尤指政府的）特工人员","lab":"especially North American English","ex":{"en":"an intelligence operative","cn":"情报人员"}},{"en":"ready to be used; in use","cn":"可使用；在使用中","g":"[not usually before noun]","ex":{"en":"This law becomes operative immediately.","cn":"本法规即时生效。"},"pos":"adjective"},{"en":"connected with a medical operation","cn":"手术的","g":"[only before noun]","lab":"medical","ex":{"en":"operative treatment","cn":"手术治疗"},"pos":"adjective"}]}},"optician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"眼镜商；验光配镜师","en":"An optician is someone whose job involves testing people's sight, and making or selling glasses and contact lenses."},{"pos":"N-COUNT 可数名词","cn":"眼镜店","en":"An optician or an optician's is a shop where you can have your eyes tested and buy glasses and contact lenses.","ex":{"en":"Some may need specialist treatment at the optician's.","cn":"有些人可能需要到眼镜店进行专业验光。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who tests people’s eyes and sells glass es in a shop 〔","cn":"眼镜店的〕验光师﹐验光配镜技师﹔眼镜商"},{"en":"someone who makes lens es for glass es","cn":"镜片制造商"}]},"vocab":{"pos":"n","senses":[{"en":"The person who makes your eye glasses is an optician . They work in the back room of the glasses shop, or at a factory, fabricating the lenses and attaching them to the frames."}]},"collocations":{"phrases":["ADJ. dispensing, ophthalmic A dispensing optician supplies glasses, but doesn't test your eyes.","PHRASES at/to the optician's I've got to go to the optician's tomorrow. • Note at DOCTOR (for verbs)"]},"media":{"img":["media/ldoce/img/optician.jpg"],"uk":"media/ldoce/hwd/bre/c/optician0205.mp3","us":"media/ldoce/hwd/ame/5/optician.mp3"},"examples":[{"en":"to go to the optician's","cn":"去眼镜店"}],"oxford":{"phon":"ɒpˈtɪʃn","pos":"noun","senses":[{"en":"a person whose job is to examine people’s eyes and to recommend and sell glasses","cn":"眼镜商；验光师","lab":"both British English"},{"en":"a person whose job is to make and supply glasses, but who does not test people's eyes","cn":"配镜师","lab":"especially North American English"},{"en":"the shop where an optician works","cn":"眼镜店","ex":{"en":"to go to the optician’s","cn":"去配眼镜"}},{"en":"a person who makes lenses, glasses, etc.","cn":"光学仪器制造者"}]}},"optional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可选择的；非强制的","en":"If something is optional, you can choose whether or not you do it or have it.","ex":{"en":"A holiday isn't an optional extra. In this stressful, frantic world it's a must","cn":"休假并非可有可无。在这个紧张而忙碌的世界，它是必不可少的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is optional, you can choose whether to do it or not","cn":""},{"en":"done because you want to do it and not because you have to – used especially about things that you do because you think they will help other people or be useful","cn":""},{"en":"if you do not have to do something, you can do it if you want, but you are not forced to do it, either by a rule or by another person, or by the situation you are in","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you can choose whether or not to do something, it is optional . Extra credit is always optional , death and taxes are not."}]},"collocations":{"phrases":["VERBS be","ADV. entirely, purely The extra language classes are entirely optional."]},"media":{"uk":"media/ldoce/hwd/bre/2/optional0205.mp3","us":"media/ldoce/hwd/ame/1/optional.mp3"},"examples":[{"en":"This model comes with a number of optional extras (= things you can choose to have but which you will have to pay extra for).","cn":"这一型号有一系列可供选择的附件，价格另计。"},{"en":"Certain courses are compulsory; others are optional.","cn":"有些课程是必修的，其他是选修的。"}],"oxford":{"phon":"ˈɒpʃənl","pos":"adjective","senses":[{"en":"that you can choose to do or have if you want to","cn":"可选择的；选修的","ex":{"en":"Certain courses are compulsory; others are optional.","cn":"有些课程是必修的，另一些是选修的。"}}]}}});
